function budgetPicker({value=2,remaining=500,onChange=()=>{}}={}){const wrap=el('div',undefined,'reviewed-budget'),label=el('label','Batch budget for this action'),input=el('input');input.type='number';input.min='1';input.max=String(Math.max(1,Math.min(500,remaining||500)));input.step='1';input.value=String(Math.min(value,Number(input.max)));label.append(input);const choose=el('button','Select remaining batches','text-button');choose.type='button';const broader=el('label',undefined,'broader-consent'),check=el('input');check.type='checkbox';broader.append(check,document.createTextNode(' I explicitly approve more than two batches in this action.'));const info=el('p',undefined,'muted');function showBound(){const budget=Number(input.value);info.textContent=`${remaining||'Remaining'} eligible batches. Default is two; selecting never starts a request. ${Number.isInteger(budget)&&budget>0?'Upper request bound: '+(2*budget)+' (including one retry per batch); completion cap 7,000 tokens per request.':'Enter a valid batch budget.'} Actual provider price is unavailable.`}showBound();function changed(){showBound();broader.hidden=Number(input.value)<=2;check.checked=false;onChange()}input.addEventListener('input',changed);check.addEventListener('change',onChange);choose.addEventListener('click',()=>{input.value=input.max;changed()});broader.hidden=Number(input.value)<=2;wrap.append(label,choose,broader,info);return{element:wrap,input,check,valid:()=>Number.isInteger(Number(input.value))&&Number(input.value)>=1&&Number(input.value)<=Number(input.max)&&(Number(input.value)<=2||check.checked),body:()=>({batchBudget:Number(input.value),...(Number(input.value)>2?{broaderBudgetApproved:check.checked}:{})})}}
